def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    if not s:
        return 0
    partes = s.split()
    minutos = 0
    for parte in partes:
        if parte.endswith('h'):
            minutos += int(parte[:-1]) * 60
        elif parte.endswith('m'):
            minutos += int(parte[:-1])
    return minutos

def es_palindromo(s):
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    return cleaned == cleaned[::-1]

def aplanar(lista):
