def contar_palabras(texto):
    import re
    palabras = re.findall(r'\b\w+\b', texto.lower())
    diccionario = {}
    for palabra in palabras:
        if palabra not in diccionario:
            diccionario[palabra] = 0
        diccionario[palabra] += 1
    return diccionario

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    letras = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    resultado = []
    for i, val in enumerate(valores):
        while n >= val:
            resultado.append(letras[i])
            n -= val

    return "".join(reversed(resultado))

def from_romano(s):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    result = 0
    prev = 0
    for char in reversed(s):
        if char in roman_map:
            value = roman_map[char]
            if prev and value < prev:
                result -= value
            else:
                result += value
            prev = value
    return result

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = 0
    max_element = None
    current_racha = 0
    current_element = None

    for i in range(len(lista)):
        if i == 0:
            current_element = lista[i]
            current_racha = 1
        else:
            if lista[i] == current_element:
                current_racha += 1
            else:
                if current_racha > max_racha:
                    max_racha = current_racha
                    max_element = current_element
                current_racha = 1
                current_element = lista[i]

    if current_racha > max_racha:
        max_racha = current_racha
        max_element = current_element

    return (max_element, max_racha)

def a_camel(s):
    if not s:
        return ""
    words = s.split()
    result = []
    for word in words:
        if word == "":
            continue
        if len(word) == 1:
            result.append(word.upper())
        else:
            result.append(word[0].lower() + word[1:].upper())
    return "".join(result)

def a_snake(s):
    if not s:
        return ""
    result = []
    prev_is_upper = False
    for char in s:
        if char.isupper():
            if prev_is_upper:
                result.append("-")
            result.append(char.lower())
            prev_is_upper = False
        else:
            result.append(char.lower())
            prev_is_upper = char.isupper()
    return "".join(result)

def primos(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

