def comprimir(s):
    if not s:
        return s

    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    compressed = []
    for char, count in counts.items():
        if count > 1:
            compressed.append(f"{char}{count}")
        else:
            compressed.append(char)

    compressed_str = "".join(compressed)

    if len(compressed_str) < len(s):
        return compressed_str
    else:
        return s

def balanceado(texto):
    if not texto:
        return True
    stack = []
    for char in texto:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and char == ')') or \
               (top == '[' and char == ']') or \
               (top == '{' and char == '}'):
                continue
            else:
                return False
    return len(stack) == 0

