def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar los intervalos por inicio
    intervalos.sort(key=lambda x: x[0])

    resultado = [intervalos[0]]

    for intervalo in intervalos[1:]:
        ultimo = resultado[-1]
        if intervalo[0] <= ultimo[1]:
            # Se tocan o superponen, se fusionan
            ultimo[1] = max(ultimo[1], intervalo[1])
        else:
            # No se tocan, se agrega como nuevo intervalo
            resultado.append(intervalo)

    return resultado

