def mediana(nums):
    if not nums:
        return None
    nums.sort()
    n = len(nums)
    if n % 2 == 1:
        return nums[n // 2]
    else:
        return (nums[n // 2 - 1] + nums[n // 2]) / 2

def top_frecuentes(texto, k):
