    words = re.findall(r'\b\w+\b', texto.lower())
    if not words:
        return []
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    sorted_words = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return sorted_words[:k]

